#define FONT5X7_GLYPH_COUNT (sizeof(FONT5X7_TABLE) / sizeof(FONT5X7_TABLE[0]))

void font5x7_lookup(char ch, uint8_t out_cols[5])
{
    char upper = (char)toupper((unsigned char)ch);

    for (size_t i = 0; i < FONT5X7_GLYPH_COUNT; i++) {
        if (FONT5X7_TABLE[i].ch == upper) {
            for (int c = 0; c < 5; c++) {
                out_cols[c] = FONT5X7_TABLE[i].cols[c];
            }
            return;
        }
    }

    // Unknown character: blank glyph rather than garbage or a crash.
    for (int c = 0; c < 5; c++) {
        out_cols[c] = 0;
    }
}